  await b.office.run('financing.connect', {}, { error: 'FORBIDDEN' })
  await h.command('financing.connect', { version: (await h.state()).business[0].version, mode: 'test', merchantId: 'synthetic-glove-merchant-1', minimumAmount: '1000.00', authToken: 'synthetic-glove-60' })
  let q = await h.command('quote.draft', { customerId: b.customer.id, siteId: b.site.id, title: 'Replace system', lines: [{ description: 'System replacement', quantity: '1', unitPrice: '9800.00', tax: 'FREE' }] })
  q = await h.command('quote.approve', { quoteId: q.id, version: q.version, revision: 1 })
  const link = await h.command('quote.link', { quoteId: q.id, version: q.version })
